import { describe, expect, it, beforeEach } from "vitest";
import request from "supertest";
import { app } from "../src/server.js";
import { cleanupRateLimiter } from "../src/middleware/rateLimiter.js";

describe("Rate Limiter", () => {
  beforeEach(() => {
    cleanupRateLimiter();
  });

  it("allows requests under the limit", async () => {
    for (let i = 0; i < 10; i++) {
      const res = await request(app).get("/notes");
      expect(res.status).toBe(200);
      expect(res.headers["x-ratelimit-limit"]).toBe("100");
      expect(res.headers["x-ratelimit-remaining"]).toBe((99 - i).toString());
    }
  });

  it("returns 429 when rate limit is exceeded", async () => {
    for (let i = 0; i < 100; i++) {
      await request(app).get("/notes");
    }

    const res = await request(app).get("/notes");
    expect(res.status).toBe(429);
    expect(res.body.error).toBe("Rate limit exceeded");
    expect(res.body.retryAfter).toBeDefined();
    expect(res.headers["retry-after"]).toBeDefined();
    expect(res.headers["x-ratelimit-remaining"]).toBe("0");
  });

  it("window resets after time passes", async () => {
    const shortWindowApp = await import("express").then((m) => m.default());
    const { createRateLimiter } = await import("../src/middleware/rateLimiter.js");

    const limiter = createRateLimiter({ windowMs: 100, maxRequests: 5 });
    shortWindowApp.use(limiter);
    shortWindowApp.get("/test", (_req, res) => res.json({ ok: true }));

    for (let i = 0; i < 5; i++) {
      const res = await request(shortWindowApp).get("/test");
      expect(res.status).toBe(200);
    }

    const blocked = await request(shortWindowApp).get("/test");
    expect(blocked.status).toBe(429);

    await new Promise((resolve) => setTimeout(resolve, 150));

    const afterReset = await request(shortWindowApp).get("/test");
    expect(afterReset.status).toBe(200);
  });
});

