import { Request, Response, NextFunction } from "express";

export interface RateLimiterOptions {
  windowMs: number;
  maxRequests: number;
}

interface WindowData {
  count: number;
  resetTime: number;
}

const windows = new Map<string, WindowData>();

export function createRateLimiter(options: RateLimiterOptions = { windowMs: 60000, maxRequests: 100 }) {
  const { windowMs, maxRequests } = options;

  return function rateLimiter(req: Request, res: Response, next: NextFunction) {
    const clientId = req.ip ?? req.socket.remoteAddress ?? "unknown";
    const now = Date.now();

    let windowData = windows.get(clientId);

    if (!windowData || now >= windowData.resetTime) {
      windowData = {
        count: 0,
        resetTime: now + windowMs,
      };
      windows.set(clientId, windowData);
    }

    windowData.count++;

    const remaining = Math.max(0, maxRequests - windowData.count);
    const retryAfter = Math.ceil((windowData.resetTime - now) / 1000);

    res.setHeader("X-RateLimit-Limit", maxRequests);
    res.setHeader("X-RateLimit-Remaining", remaining);
    res.setHeader("X-RateLimit-Reset", Math.ceil(windowData.resetTime / 1000));

    if (windowData.count > maxRequests) {
      res.setHeader("Retry-After", retryAfter);
      res.status(429).json({
        error: "Rate limit exceeded",
        retryAfter,
      });
      return;
    }

    next();
  };
}

export function cleanupRateLimiter() {
  windows.clear();
}

